def rotmat(axis,ang):
    ax=axis/np.linalg.norm(axis); c=np.cos(ang); s=np.sin(ang)
    return np.eye(3)*c+np.outer(ax,ax)*(1-c)+s*np.array([[0,-ax[2],ax[1]],[ax[2],0,-ax[0]],[-ax[1],ax[0],0]])

def score(ids, others, Pt):
    E=0.
    for i in ids:
        pi=Pt[i]
        d=np.linalg.norm(Pt[others]-pi,axis=1)
        E+=np.sum(np.exp(-2.5*(d-1.0)))
    return E

def optimize_rotor(center_idx, axis_idx, ids, Pt):
    excl_local=set(ids)|{center_idx,axis_idx}
    others=np.array([j for j in range(n) if j not in excl_local and (min(ids)>j or True)])
    others=np.array([j for j in range(n) if j not in excl_local])
    axis=Pt[axis_idx]-Pt[center_idx]
    best=(1e18,0.)
    for angd in np.arange(0,120,10):
        R=rotmat(axis,np.radians(angd))
        Pt2=Pt.copy()
        for i in ids: Pt2[i]=Pt[center_idx]+R@(Pt[i]-Pt[center_idx])
        s=score(ids,others,Pt2)
        if s<best[0]: best=(s,angd)
    # refine
    lo,hi=best[1]-10,best[1]+10
    for angd in np.arange(lo,hi,2.5):
        R=rotmat(axis,np.radians(angd))
        Pt2=Pt.copy()
        for i in ids: Pt2[i]=Pt[center_idx]+R@(Pt[i]-Pt[center_idx])
        s=score(ids,others,Pt2)
        if s<best[0]: best=(s,angd)
    R=rotmat(axis,np.radians(best[1]))
    for i in ids: Pt[i]=Pt[center_idx]+R@(Pt[i]-Pt[center_idx])
    return best[0]

